import{_ as e,o as a,b as s,q as t}from"./chunks/framework.Tf23FRXt.js";const d="/assets/f6af86aa10790fa9bb9649f256afc1049ec9d0.JJOC04wV.jpg",l="/assets/48731cb8e728cd5076ba694b9a6551e17ecc7c.ZO3vVojO.jpg",n="/assets/e50360ed08e9a4e2c935c27464e0169ab09df4.Dr7Km056.jpg",r="/assets/7d905e1eaba784998091c7d770c58d4fd124c2.C2XE5YoH.jpg",c="/assets/35b20a15267018c7739b0458c476d6f5f2da91.5iP-jel8.jpg",p="/assets/73d9b43dd0062292aad79f3e39d7f70afb55c8.B5O8fMrS.jpg",o="/assets/7982fde78996e78f6bf63deec986a29e083931.BCY6SdUi.jpg",g="/assets/fb7ada3aa74da68150717ca563a67d3201198a.DMI_qKLu.jpg",v="/assets/a95edf4696f3afc3b6b1f9e69eaee605678f6d.D4YTu6dC.jpg",x=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[{"level":2,"title":"切换操作模式","slug":"切换操作模式","link":"#切换操作模式","children":[{"level":3,"title":"Q: 想使用键盘鼠标操作","slug":"q-想使用键盘鼠标操作","link":"#q-想使用键盘鼠标操作","children":[]},{"level":3,"title":"Q: 想用手柄操作","slug":"q-想用手柄操作","link":"#q-想用手柄操作","children":[]}]},{"level":2,"title":"界面的查看方法","slug":"界面的查看方法","link":"#界面的查看方法","children":[{"level":3,"title":"Q: 不知道怎么看游戏界面","slug":"q-不知道怎么看游戏界面","link":"#q-不知道怎么看游戏界面","children":[]},{"level":3,"title":"Q: 为什么任务图标不一样？","slug":"q-为什么任务图标不一样","link":"#q-为什么任务图标不一样","children":[]}]},{"level":2,"title":"周辺機器","slug":"周辺機器","link":"#周辺機器","children":[{"level":3,"title":"Q: 手柄按键的显示设置选哪个好？","slug":"q-手柄按键的显示设置选哪个好","link":"#q-手柄按键的显示设置选哪个好","children":[]},{"level":3,"title":"Q: 想用手柄进行鼠标操作","slug":"q-想用手柄进行鼠标操作","link":"#q-想用手柄进行鼠标操作","children":[]}]}],"relativePath":"ui/faq.htm.md","filePath":"ui/faq.md","lastUpdated":1791098838000}'),f={name:"ui/faq.htm.md"};function _(h,i,u,b,m,q){return a(),s("div",null,[...i[0]||(i[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题</h1><h2 id="切换操作模式" tabindex="-1">切换操作模式</h2><h3 id="q-想使用键盘鼠标操作" tabindex="-1">Q: 想使用键盘鼠标操作</h3><div class="guide cols2"><div class="guide col"><p><img src="'+d+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>切换操作模式，可以使用角色设置左上角的切换按钮进行。</p><p>快捷指令中打开角色设置，把切换按钮切到 “键盘鼠标模式” 就可以了。</p></div></div><h3 id="q-想用手柄操作" tabindex="-1">Q: 想用手柄操作</h3><div class="guide cols2"><div class="guide col"><p><img src="'+l+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>想用控制器或者手柄操作的话，从快捷指令中打开角色设置，把切换按钮切到手柄模式就可以了。</p></div></div><h2 id="界面的查看方法" tabindex="-1">界面的查看方法</h2><h3 id="q-不知道怎么看游戏界面" tabindex="-1">Q: 不知道怎么看游戏界面</h3><p>最终幻想 14 根据你使用的操作方法不同，游戏界面中所展示的界面部件和布局都会有所区别。所有部件的名字和详细说明请查看<a href="https://jp.finalfantasyxiv.com/uiguide/know/#category-know-hud" target="_blank" rel="noreferrer">这里</a>。</p><div class="guide cols2"><div class="guide col figcap"><p><img src="'+n+'" alt="" loading="lazy"></p><p>键盘鼠标模式</p></div><div class="guide col figcap"><p><img src="'+r+'" alt="" loading="lazy"></p><p>手柄操作模式</p></div></div><h3 id="q-为什么任务图标不一样" tabindex="-1">Q: 为什么任务图标不一样？</h3><p>最终幻想 14 里，可以接到任务的角色头顶会出现任务图标。重要的任务（主线任务）的图标和普通的图标不一样，形状也很特殊。</p><div class="guide center"><p><img src="'+c+'" alt="" loading="lazy"></p></div><p>完成任务可以获得大量经验，还有丰厚报酬，很适合用来升级。如果不知道先做哪个任务号，推荐先推进主线任务。另外也推荐 “开放功能任务”，完成后可以获得专属陆行鸟、开放新的迷宫等等，会开放各种各样的新功能，不要忘记做这些任务哦。</p><h5 id="图标的变化" tabindex="-1">图标的变化</h5><p>任务图标会根据任务进行的状况而发生变化。图标是红色的时候，是有某种原因而无法接受或进行。具体信息的话可以在日志中确认。日志在快捷指令 &gt; 任务情报中查看。</p><div class="guide center"><p><img src="'+p+'" alt="" loading="lazy"></p></div><p>另外，还有各种各样的相关图标。具体可以查看<a href="https://jp.finalfantasyxiv.com/lodestone/playguide/win/view/#g_npc" target="_blank" rel="noreferrer">这里</a>。</p><h2 id="周辺機器" tabindex="-1">周辺機器</h2><h3 id="q-手柄按键的显示设置选哪个好" tabindex="-1">Q: 手柄按键的显示设置选哪个好？</h3><div class="guide cols2"><div class="guide col"><p><img src="'+o+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>PC 版中，手柄按键的设置可以自由变更，选择用起来更顺手的那个吧。</p><p><strong>ABXY</strong><br> 按 XInput 的标准显示按键字母<br><strong> ×○□△</strong><br> 按 PlayStation®3 的标准显示按键记号<br><strong> ×○□△ + 触摸板</strong><br> 按 PlayStation®4 的标准显示按键记号</p><p>※手柄设置在系统中的手柄设置中进行。<br> ※变更按键类型需要重新启动游戏。</p></div></div><h3 id="q-想用手柄进行鼠标操作" tabindex="-1">Q: 想用手柄进行鼠标操作</h3><div class="guide cols2"><div class="guide col"><p><img src="'+g+'" alt="" loading="lazy"></p></div><div class="guide col"><p><img src="'+v+'" alt="" loading="lazy"></p></div></div><p>在最终幻想 14 中，打开虚拟鼠标功能，就可以把手柄当做鼠标来使用。</p><p>虚拟鼠标的话，从快捷指令 &gt; 系统设置中的手柄设置里进行修改，勾选 “启用虚拟鼠标” 即可。</p><p><strong>打开 / 关闭虚拟鼠标模式</strong><br> Windows 版：L 键（LB）+ 右摇杆按键</p><p><strong>移动光标</strong><br> Windows 版：右摇杆</p><p><strong>左键单击 / 右键单击</strong><br> Windows 版：LT 键 / RT 键</p><p>相关阅读：<br><a href="https://jp.finalfantasyxiv.com/uiguide/know/#entry-hotbar_pad_registration" target="_blank" rel="noreferrer">Q: 只有手柄的话，可以设置热键栏吗？</a></p>',29)])])}const y=e(f,[["render",_]]);export{x as __pageData,y as default};
